def apply(inputs, premises):
    question = inputs["current_question"]
    is_employee_query = "Receiving Party may share some Confidential Information" in question and "employees" in question
    permission = False
    prohibition = False
    if "employee_disclosure_expressly_permitted" in premises:
        permission = premises["employee_disclosure_expressly_permitted"]
    if "employee_disclosure_expressly_prohibited" in premises:
        prohibition = premises["employee_disclosure_expressly_prohibited"]
    if not is_employee_query:
        answer = "NotMentioned"
    elif permission:
        answer = "Entailment"
    elif prohibition:
        answer = "Contradiction"
    else:
        answer = "NotMentioned"
    return {"answer": answer}
